WITH payload AS (SELECT $archive_payload$[{"id":"20846168-e766-5dd2-b296-12726845b0d1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حيازة مخدرات قبل صدور نظام مكافحة املخدرات راجعة لولي األمر -إقرار -إدانة -تداخل احلدود -إذا كانت من جنس واحد -االكتفاء بالعقوبة السابقة.","document_number":"3413958","case_number":"3423403","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/13","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حيازة مخدرات قبل صدور نظام مكافحة املخدرات راجعة لولي األمر -إقرار -إدانة -تداخل احلدود -إذا كانت من جنس واحد -االكتفاء بالعقوبة السابقة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3413958:‬تاريخه‪1434/01/13 :‬هـ‬\n                    ‫رقم الدعوى‪3423403:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34169534‬تاريخه‪1434/3/23 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‬\n‫وتعاطيهــا ‪ -‬حيــازة مخــدرات قبــل صــدور نظــام مكافحــة املخــدرات‬\n‫راجعــة لولــي األمــر ‪ -‬إقــرار‪ -‬إدانــة‪ -‬تداخــل احلــدود ‪ -‬إذا كانــت مــن‬\n                     ‫جنــس واحــد ‪ -‬االكتفــاء بالعقوبــة الســابقة‪.‬‬\n\n\n\n\n                                    ‫‪ -1‬اإلقرار حجة على املقر‪.‬‬\n                                             ‫‪ -2‬ال عذر ملن أقر‪.‬‬\n       ‫‪ -3‬احلدود إذا كانت من جنس واحد ولم تقم أجزأ حد واحد‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش‬\n‫املخــدر وحبــوب اإلمفيتامــن احملظــورة بقصــد االســتعمال وتعاطيــه‬\n‫لهــا‪ ،‬وإفهامــه بــأن عقوبتــه علــى ذلــك عائــد لولــي األمــر (الواقعــة قبــل‬\n‫صــدور نظــام مكافحــة املخــدرات واملؤثــرات العقليــة)‪ ،‬حيــث إنــه مت‬\n‫تفتيــش ســيارة املدعــى عليــه بعــد االشــتباه بــه فعثــر فيهــا علــى احلشــيش‬\n‫املخــدر وحبــوب اإلمفيتامــن احملظــورة وعلــى مســكر خارجــي‪ ،‬وأثبــت‬\n‫التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش‬\n‫املخــدر واإلمفيتامــن‪ ،‬كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه‬\n\n                                                                                     ‫‪92‬‬\n\f     ‫املدعــي العــام‪ ،‬وحيــث إن احملكمــة اطلعــت علــى حكــم صــادر بحقــه‬\n     ‫يتضمــن إقامــة حــد املســكر عليــه فوجــدت تاريخــه الحــق لتاريــخ‬\n     ‫الواقعــة املطروحــة أمامهــا‪ ،‬مــن املقــرر شــرع ًا أن احلــدود إذا كانــت‬\n     ‫مــن جنــس واحــد ولــم تقــم أجــزأ حــد واحــد‪ ،‬فقضــت احملكمــة بإدانــة‬\n     ‫املدعــى عليــه بجميــع مــا نســب إليــه وقــررت االكتفــاء عــن احلكــم بحــد‬\n     ‫املســكر علــى املدعــى عليــه مبــا مت احلكــم به عليه يف احلكم الســابق‪،‬‬\n     ‫وأفهمتــه بــأن عقوبتــه علــى احليــازة لقصــد االســتعمال راجعــة لولــي األمــر‬\n     ‫(اجلهــة املختصــة)‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                 ‫عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪........‬القاضــي باحملكمــة اجلزئيــة‬\n     ‫بالقطيــف بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم‬\n     ‫‪ 3423403‬يف ‪1434/1/13‬ه ـ والــواردة بكتــاب مديــر مكافحــة‬\n     ‫املخــدرات بالدمــام رقــم ‪ 25/1/3/15‬يف ‪1434/1/7‬ه ـ حضــر املدعــي‬\n     ‫العــام ‪........‬مبــن قبــل مكافحــة املخــدرات وادعــى علــى احلاضــر معــه‬\n     ‫ا يف دعــواه إنــه بتاريــخ ‪1424/9/2‬هـ مت‬    ‫حامــل الســجل املدنــي رقــم قائـ ً‬\n     ‫القبــض علــى املدعــو‪ ........‬ســعودي اجلنســية مــن قبــل رجــال امــن الطــرق‬\n     ‫اثــر االشــتباه بــه بنقطــة تفتيــش وبرفقــة املدعــو ‪ ........‬بتفتيــش ســيارتهما‬\n     ‫وعثــر علــى مبلــغ مالــي وعــدد (‪ )33‬حبــه ثالثــة وثالثــون حبــه مــن‬\n     ‫اإلمفيتامــن املنبهــة ووجــد أيضـاً» قطعــه بنيــة اللــون يشــتبه أنهــا حشــيش‬\n     ‫مخــدر تــزن (‪ )1,15‬جــم وكذلــك ســيجارتني ملفوفــه يشــتبه أنهــا‬\n     ‫مخلوطــة باحلشــيش املخــدر تــزن (‪ )2,27‬جــم أثبــت التقريــر الكيمــاوي‬\n\n‫‪93‬‬\n\f‫الشــرعي رقــم (‪ )........‬يف ‪1424/9/7‬ه إيجابيتهــا ملركــب احلشــيش‬\n‫املخــدر وحبــوب اإلمفيتامــن املنبهــة واحملضــورة وبعــد اعــادة تفتيــش‬\n‫الســيارة وجــد بطبلــون الســيارة االمامــي عــدد (‪ )24‬قــارورة مســكر‬\n‫خارجــي ووجــد بــن املرتبــة اخللفيــة للســيارة والشــنطة (‪ )81‬قــارورة‬\n‫مــن نفــس النــوع اثبــت التقريــر الكيمــاوي املنــوه أعــاه إيجابيتهــا ملــادة‬\n‫الكحــول األثيلــي املســكر وبالبحــث عمــا اذا كان لــه ســوابق عثــر لــه‬\n‫علــى ثــاث ســوابق اثنتــان ســكر وواحــده مخــدرات وملــا للمخــدرات مــن‬\n‫اضــرار جســيمه علــى الفــرد واالســرة واملجتمــع وألجــل احلــق العــام فإننــي‬\n‫اطلــب مــن فضيلتكــم إثبــات ادانتــه بحيــازة مــا عــدده (‪ )33‬حبــه ثالثــة‬\n‫وثالثــون حبــه مــن حبــوب اإلمفيتامني وحيازة قطعه من احلشــيش املخدر‬\n‫تــزن (‪ )1,15‬جــم وحيــازة ســيجارتني (‪ )2,27‬جــم بقصــد االســتعمال‬\n‫وافهامــه بــأن عقابــه علــى ذلــك عائــد لولــي األمــر واحلكــم عليــه بحــد‬\n‫املســكر لقــاء اعترافــه بتعاطــي احلشــيش املخــدر واحلبــوب اإلمفيتامــن‬\n‫وشــربه للمســكر واحلكــم عليــه لقــاء تكــرار ســوابقه التــي لــم تردعــه‬\n‫عقوباتهــا الســابقة هــذا مــا ادعــى بــه وبعرضــه علــى املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه ضــدي‬     ‫وبســؤاله عنــه أجــاب قائ ـ ً‬\n‫مــن اتهامــي بحيــازة الكميــة التــي ذكــر مــن احلبــوب واحلشــيش املخــدر‬\n‫والســيجارتني املذكورتــن لقصــد االســتعمال وأنــي قمــت بتعاطــي حبــة‬\n‫مــن احلبــوب احملظــورة وســيجارة احلشــيش كلــه صحيــح ومــا ســوى ذلــك‬\n‫فــا أعلــم عنــه هــذا مــا أجــاب بــه وقــد جــرى االطــاع علــى التقريــر‬\n‫الكيميائــي الشــرعي رقــم ‪........‬يف ‪1424/9/7‬ه ـ والــذي يتضمــن‬\n‫مطابقتــه ملــا عطفــه عليــه املدعــي العــام وقــد جــرى االطــاع علــى صــورة‬\n‫القــرار الشــرعي رقــم ‪ 33475052‬يف ‪1433/12/21‬ه ـ الصــادر مــن‬\n\n\n                                                                                     ‫‪94‬‬\n\f     ‫فضيلــة القاضــي باحملكمــة اجلزائيــة بالقطيــف الشــيخ والــذي يتضمــن‬\n     ‫احلكــم علــى املدعــى عليــه بجلــده ثمانــن جلــدة دفعــة واحــدة حــد‬\n     ‫املســكر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى‬\n     ‫عليــه بتعاطيــه حلبــة مــن احلبــوب احملظــورة ولســيجارة خلطــت باحلشــيش‬\n     ‫وحيازتــه للحبــوب والقطعــة والســيجارتني املذكــورات يف الدعــوى وألن‬\n     ‫اإلقــرار حجــة علــى املقــر وال عــذر ملــن أقــر وألن احلــدود إذا كانــت مــن‬\n     ‫جنــس واحــد ولــم تقــم أجــزأ حــد واحــد لــذا فقــد ثبــت لدي حيــازة املدعى‬\n     ‫عليــه للكميــة املوصوفــة يف الدعــوى مــن احلبــوب احملظــورة ومــن قطعــة‬\n     ‫احلشــيش ومــن الســيجارتني لقصــد االســتعمال وقيامــه بتعاطــي حبــة مــن‬\n     ‫احلبــوب احملظــورة ولســيجارة خلطــت باحلشــيش وقــررت االكتفــاء عــن‬\n     ‫احلكــم بحــد املســكر علــى املدعــى عليــه مبــا مت احلكــم بــه عليــه فيــه‬\n     ‫بالقــرار الشــرعي رقــم ‪ 33475052‬يف ‪1433/12/21‬ه ـ وبــه حكمــت‬\n     ‫وأفهمــت املدعــى عليــه بــأن عقابــه علــى حيازتــه للكميــة املوصوفــة يف‬\n     ‫الدعــوى مــن احلبــوب احملظــورة ومــن قطعــة احلشــيش ومــن الســيجارتني‬\n     ‫لقصــد االســتعمال راجــع لولــي األمــر ففهمــه وبعــرض احلكــم علــى‬\n     ‫الطرفــن اعتــرض عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي‬\n     ‫الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه وســيتم بعــث كامــل املعاملــة‬\n     ‫حملكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف‬\n     ‫‪1434/1/17‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n     ‫أجمعــن‪ .‬احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف بالدمــام بكتــاب فضيلــة رئيســها رقــم ‪ 34273497‬يف‬\n     ‫‪1434/4/6‬ه ـ املقيــدة يف هــذه احملكمــة برقــم ‪ 34861161‬يف‬\n     ‫‪1434/4/8‬ه ـ واحملالــة مــن فضيلــة الرئيــس وبرفقهــا إعــام احلكــم‬\n\n\n‫‪95‬‬\n\f‫الصــادر منــي برقــم ‪ 3413958‬يف ‪1434/1/17‬ه ـ وبرفقهــا قــرار‬\n‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى رقــم ‪ 34169534‬يف‬\n‫‪1434/3/23‬ه ـ ونصــه بعــد املقدمــة وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وآلــه وصحبــه وســلم قاضــي اســتئناف ‪ .....‬ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه رئيــس الدائــرة ختمــه‬\n‫وتوقيعــه أ‪.‬ه ـ وللبيــان حــرر يف ‪1434/4/9‬ه ـ وصلــى اهلل وســلم علــى‬\n                               ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                                ‫‪96‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":92,"source_page_end":96,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2b33bee60801825b28b12226cceaa6e21c9d47ff87c9ab66c27cd9891b64c463","normalized_text_hash":"125c4afd6b4b7a69c79cae68cea58d8883ee6e77f07107f626e88dbd569cf1fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p92-3413958"},{"id":"7275bb71-cca4-5e8b-ac96-a30cace3cb1c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة سيجارة بداخلها نبات احلشيش املخدر -تعاطي لفافة تبغ بداخلها نبات احلشيش املخدر -اإلقرار حجة على صاحبه -تعزير بالسجن واجللد واملنع من السفر.","document_number":"3414438","case_number":"3423430","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/18","year":"1434","subject":"مخدرات -حيازة سيجارة بداخلها نبات احلشيش املخدر -تعاطي لفافة تبغ بداخلها نبات احلشيش املخدر -اإلقرار حجة على صاحبه -تعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3414438 :‬تاريخه ‪1434/01/18 :‬هـ‬\n                          ‫رقم القضية ‪3423430 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34299912‬تاريخه ‪1434/08/17 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة ســيجارة بداخلهــا نبــات احلشــيش املخــدر ‪ -‬تعاطــي‬\n      ‫لفافــة تبــغ بداخلهــا نبــات احلشــيش املخــدر ‪ -‬اإلقــرار حجــة علــى‬\n                     ‫صاحبــه ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n                             ‫‪ -1‬قاعدة ‪ :‬اإلقرار حجة على صاحبه مؤاخذ به‪.‬‬\n      ‫‪ -2‬مــا روى ابــن عمــر رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه‬\n            ‫وســلم قــال ‪« :‬كل مســكر خمــر وكل خمــر حــرام» رواه مســلم ‪.‬‬\n      ‫‪ -3‬قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل يف احلشيشــة ‪ ( :‬الــذي‬\n      ‫عليــه جمهــور األئمــة أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلها‬\n                                            ‫يحــد ) مجمــوع الفتــاوى ‪. 358/23‬‬\n                              ‫‪ -4‬املادتان (‪41‬و‪ )60‬من نظام مكافحة املخدرات‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليــه بحيــازة ســيجارة حشــيش ‪ ،‬وأعقــاب‬\n      ‫ســجائر حشــيش ‪ ،‬وثالثــة مشــارط تســتخدم لتقطيــع احلشــيش وتعاطيــه‬\n      ‫للحشــيش املخــدر ‪ ،‬ورد إلدارة مكافحــة املخــدرات خطــاب مديــر‬\n      ‫الشــرطة املتضمــن أنــه بعــد القبــض علــى املدعــى عليــه يف قضيــة‬\n      ‫ســرقة (فــرزت لهــا أوراق مســتقلة) عثــر بحوزتــه علــى ســيجارة ملفوفــة‬\n\n‫‪97‬‬\n\f‫باحلشــيش وأعقــاب ســجائر حشــيش وثالثــة مشــارط يعلوهــا آثــار حــرق‬\n‫نــار يشــتبه أنهــا تســتخدم يف تقطيــع احلشــيش املخــدر‪ ،‬طلــب املدعــي‬\n‫العــام إثبــات إدانتــه مبــا نســب إليــه ‪ ،‬واحلكــم عليــه بالســجن واملنــع مــن‬\n‫الســفر وفق ـ ًا لنظــام مكافحــة املخــدرات ‪ ،‬احلكــم عليــه باملقتضــى‬\n‫الشــرعي لقــاء تعاطيــه املخــدر ‪ ،‬أقــر املدعــى عليــه مبــا نســب إليــه ‪،‬‬\n‫صــدر احلكــم بإثبــات إدانــة املدعــى عليــه مبــا نســب إليــه واحلكــم عليــه‬\n‫بإقامــة حــد املســكر علنـ ًا والتعزيــر بالســجن واجللــد واملنــع مــن الســفر‪،‬‬\n                                 ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .......‬القاضــي باحملكمــة اجلزائيــة‬\n‫بتبــوك القائــم بعمــل فضيلــة الشــيخ ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بتبــوك بنــاء علــى املعاملــة احملالــة مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n‫بتبــوك املكلــف برقــم ‪ 3423430‬وتاريــخ ‪1434/01/13‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34112149‬وتاريــخ ‪1434/01/13‬ه ـ عليــه ففــي‬\n‫يــوم الثالثــاء املوافق‪1434/01/13‬ه ـ افتتحــت اجللســة الســاعة الواحــدة‬\n‫وفيهــا حضــر املدعــي العــام املكلــف مــن هيئــة التحقيــق واالدعــاء العــام‬\n‫بخطــاب رقــم‪ .......‬وتاريــخ ‪1433/9/5‬ه ـ وادعــى علــى احلاضــر معــه‬\n‫‪.......‬ســعودي مبوجــب ســجل مدنــي رقــم‪ .......‬قائــا يف حتريــر دعــواه أنــه‬\n‫بتاريــخ ‪1430/3/ 13-12‬ه ـ ورد لــإدارة العامــة ملكافحــة املخــدرات‬\n‫مبنطقــة تبــوك خطــاب مديــر شــرطة ‪ .......‬مبدينــة تبــوك بالرقــم‬\n‫‪ 22/137/28‬وتاريــخ ‪1430/2/13‬ه ـ بشــأن كل مــن املدعــو‪.......‬‬\n‫واملدعــو‪ .......‬واملدعــو‪( .......‬حفــظ االتهــام بحقهــم وبحــق املدعــو لعــدم‬\n\n                                                                                       ‫‪98‬‬\n\f     ‫كفايــة األدلــة واســتنادا للمــادة (‪ )124‬مــن نظــام اإلجــراءات اجلزائيــة)‬\n     ‫واملتهــم املذكــور أعــاه واملتهمــن بقضيــة تكســير زجــاج ســيارات‬\n     ‫وســرقتها ( فــرزت أوراق مســتقلة مــن قبــل املكافحــة لقضيــة تكســير‬\n     ‫زجــاج الســيارات وســرقتها وأحيلــت مــع املتهمــن بعــد اإلفــراج عنهــم مــن‬\n     ‫قبلنــا بالكفالــة احلضوريــة اســتنادا للمــادة (‪ )120‬مــن نظــام األجــراءات‬\n     ‫اجلزائيــة ملركــز شــرطة ‪ .......‬إلكمــال الــازم مــن قبلهــم بحكــم‬\n     ‫االختصــاص ) وعثــر بحــوزة املتهــم املذكــور علــى ســيجارة ملفوفــة‬\n     ‫يدويــا بلــغ وزنهــا (‪ )700‬ســبعمائة مليجــرام وأعقــاب ســجائر بلــغ زونهــا‬\n     ‫(‪900‬ملجــم ‪1 /‬جــرام) جرامــا واحــد وتســعمائة مليجــرام يشــبته أن‬\n     ‫تكــون مــن احلشــيش املخــدر وثالثــة مشــارط ( شــفرات) يعلوهــا آثــار‬\n     ‫حــرق نــار يشــتبه أنهــا تســتخدم يف تقطيــع احلشــيش املخــدر فتــم القبــض‬\n     ‫عليــه وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم ( ‪400‬م ‪ /‬م س‬\n     ‫ت) لعــام ‪1430‬ه ـ الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n     ‫الشــرعية بتبــوك إيجابيــة مــا مت ضبطــه للحشــيش املخــدر وباســتجواب‬\n     ‫املتهــم‪ .......‬أقــر بحيازتــه لســيجارة ملفوفــة يدويــا بلــغ زنهــا (‪)700‬‬\n     ‫ســبعمائة مليجــرام وأعقــاب ســجائر بلــغ زونهــا (‪900‬ملجــم ‪1 /‬جــرام)‬\n     ‫جرامــا واحــدا وتســعمائة مليجــرام يشــبته أن تكــون مــن احلشــيش‬\n     ‫املخــدر وثالثــة مشــارط ( شــفرات) يعلوهــا آثــار حــرق نــار يشــتبه أنهــا‬\n     ‫تســتخدم يف تقطيــع احلشــيش ثبــت إيجابيتهــا للحشــيش املخــدر بقصــد‬\n     ‫التعاطــي وأنــه يتعاطــى احلشــيش املخــدر منــذ شــهر ونصــف الشــهر وأنــه‬\n     ‫يحصــل عليــه مــن حــي ‪ .......‬مــن شــخص ال يعرفــه مببلــغ وقــدره (‪)20‬‬\n     ‫عشــرين ريــاال وأن ال عالقــة لزمالئــه مبــا ضبــط وال يعلمــون عنــه شــيئا‬\n     ‫إال بعــد القبــض عليــه (وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق‬\n\n\n‫‪99‬‬\n\f‫حتــى تاريخــه) وملــا أشــير أقــرر توجيــه االتهــام للمدعــو بحيازته لســيجارة‬\n‫ملفوفــة يدويــا بلــغ زنهــا (‪ )700‬ســبعمائة مليجــرام وأعقــاب ســجائر بلــغ‬\n‫زونهــا (‪900‬ملجــم ‪1 /‬جــرام) جرامــا واحــد وتســعمائة مليجــرام يشــبته‬\n‫أن تكــون مــن احلشــيش املخــدر وثالثــة مشــارط (شــفرات) يعلوهــا آثــار‬\n‫حــرق نــار ثبــت إيجابيتهــا للحشــيش اســتنادا للمــادة الثالثــة الفقــرة (‪)2‬‬\n‫مــن نظــام مكافحــة املخــدرات الصــادر باملرســوم امللكي رقــم (م ‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ وتعاطيــه للحشــيش املخــدر يف الســابق وذلــك‬\n‫لألدلــة والقرائــن التاليــة ‪ -1‬اعترافــه املنــوه عنــه واملــدون الصفحتــن‬\n‫رقــم (‪ ) 1.2‬مــن دفتــر التحقيــق املرفــق برقــم (‪ -2 )29‬مــا جــاء بخطــاب‬\n‫مديــر مركــز شــرطة ‪ .......‬املنــوه عنــه املوجــه ملديــر مكافحــة املخــدرات‬\n‫مبنطقــة تبــوك املرفــق برقــم (‪ -3 )9‬التقريــر الكيميائــي الشــرعي‬\n‫املنــوه عنــه املرفــق برقــم (‪ )39‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n‫املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامــا اســتناد ًا للمــادة‬\n‫الثالثــة الفقــرة الثانيــة مــن نظــام املخــدرات واملؤثــرات العقليــة وأطلــب مــا‬\n‫يلــي‪ -1 :‬إثبــات إدانتــه مبــا أســند إليــه ‪ -2‬احلكــم عليــه بالســجن لقــاء‬\n‫مــا أســند إليــه اســتنادا للفقــرة (‪ )1‬مــن املــادة ‪ 41‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة املشــار إليــه ‪ -3‬احلكــم مبنعــه مــن‬\n‫الســفر خــارج اململكــة بعــد انتهــاء محكومتيــه اســتنادا للمــادة ‪1/56‬‬\n‫مــن نفــس النظــام ‪ -4‬احلكــم عليــه باملتقضــي الشــرعي لقــاء تعاطيــه‬\n‫احلشــيش املخــدر هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه وســؤاله‬\n‫عنــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن حيازتــي‬\n‫لقطعــة مــن احلشــيش املخــدر املوصوفــة بالدعــوى وأعقــاب الســجائر‬\n‫املخلوطــة باحلشــيش املخــدر وثالثــة مشــارط بقصــد التعاطــي وأنــي‬\n\n\n                                                                                         ‫‪100‬‬\n\f      ‫تعاطيــت احلشــيش فصحيــح كلــه هكــذا أجــاب فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وملَّــا أقــر املدعــى عليــه بحيازتــه لقطعــة احلشــيش‬\n      ‫املخــدر املوصوفــة يف الدعــوى وأعقــاب الســجائر مخلوطــة باحلشــيش‬\n      ‫بقصــد التعاطــي والتــي ثبــت ايجابيتهــا ملــادة احلشــيش املخــدر مبوجــب‬\n      ‫التقرير الكيميائي الشرعي رقم (‪400‬م‪/‬م س ت) لعام ‪1430‬هـ كما‬\n      ‫أقــر بتعاطيــه للحشــيش وحيازتــه لثــاث مشــارط لهــذا الغــرض وحيــث‬\n      ‫إن اإلقــرار حجــة علــى صاحبــه مؤاخــذ بــه وملــا روى ابــن عمــر رضــي اهلل‬\n      ‫عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم قــال (كل مســكر خمــر‬\n      ‫وكل خمــر حــرام) رواه مســلم قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل‬\n      ‫يف احلشيشــة (الــذي عليــه جمهــور األئمــة أن قليلهــا وكثيرهــا حــرام بــل‬\n      ‫الصــواب أن آكلهــا يحــد) مجمــوع الفتــاوى ‪ 358/23‬ونظــر ًا لضآلــة‬\n      ‫الكميــة املضبوطــة بحــوزة املدعــى عليــه وعــدم وجــود ســوابق لــه وبنــاء‬\n      ‫علــى املــادة (‪ )60-56-41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫ـدي إدانــة املدعــى عليــه بحيازتــه لســيجارة ملفوفــة‬   ‫العقليــة فقــد ثبــت لـ َّ‬\n      ‫يدويــا بلــغ زنهــا ســبعمائة مليجــرام وأعقــاب ســجائر بلــغ زونهــا جرامــا‬\n      ‫واحــد ًا وتســعمائة مليجــرام مــن احلشــيش املخــدر وثالثــة مشــارط‬\n      ‫بقصــد التعاطــي وتعاطيــه لنوعــه وقــررت مــا يلــي أو ًال تعزيــر املدعــى‬\n      ‫عليــه بســجنه ملــدة شــهرين يحتســب مــن ذلــك مــدة إيقافــه بســبب هــذه‬\n      ‫القضيــة ثانيـ ًا منــع املدعــى عليــه مــن الســفر خــارج اململكــة ملــدة ســنتني‬\n      ‫بعــد انتهــاء فتــرة محكوميتــه ثالث ـ ًا جلــد املدعــى عليــه حــد املســكر‬\n      ‫ثمانــن جلــدة لقــاء تعاطيــه للحشــيش وبذلــك حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه وأمــا املدعــي العــام فقــد‬\n      ‫قــرر اعتراضــه مكتفي ـ ًا مبــا جــاء يف أوراق املعاملــة عــن تقــدمي الئحــة‬\n\n\n‫‪101‬‬\n\f‫اعتراضيــة واختتمــت اجللســة الســاعة الواحــدة والنصــف وللبيــان حــرر‬\n‫يف ‪1434/1/13‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                       ‫أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة‬\n‫الثانيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة‬\n‫مــن احملكمــة اجلزائيــة بتبــوك برقــم وتاريــخ ‪1434/8/6‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي برقــم ‪3414438‬وتاريــخ‬\n‫‪1434/1/18‬هـ ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ .......‬يف قضيــة‬\n‫حيــازة و اســتعمال مخــدرات علــى النحــو املوضــح يف القــرار واملتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه‬\n‫إلــى إضافــة كلمــة « علنـاً» إلــى حكمــه باحلــد ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                   ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":97,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7d964d924cf19ce7f9887a11b8fa5feff7d3fae95a53ec66782c54e15164a98c","normalized_text_hash":"adc6abbfdeb1d052076c02adf67e5fbe1f0d190d9eb813752625589413101a1b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p97-3414438"},{"id":"1f1be4b5-f203-5ec8-987b-69b8748b6db0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب اإلمفيتامن احملظورة بقصد التعاطي -تعاطي احلبوب احملظورة-قيادة السيارة حتت تأثير احلبوب احملظورة-تعزير املدعى عليه بالسجن واجللد واملنع من السفر- ترك مجازاة املدعى عليه لقاء قيادته للسيارة حتت تأثير احلبوب احملظورة للجهة املختصة-التعزير بالسجن واجللد واملنع من السفر -أسباب تخفيف العقوبة .","document_number":"3423765","case_number":"34165124","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/27","year":"1434","subject":"مخدرات -حيازة حبوب اإلمفيتامن احملظورة بقصد التعاطي -تعاطي احلبوب احملظورة-قيادة السيارة حتت تأثير احلبوب احملظورة-تعزير املدعى عليه بالسجن واجللد واملنع من السفر- ترك مجازاة املدعى عليه لقاء قيادته للسيارة حتت تأثير احلبوب احملظورة للجهة املختصة-التعزير بالسجن واجللد واملنع من السفر -أسباب تخفيف العقوبة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3423765 :‬تاريخه ‪1434/05/27:‬هـ‬\n                         ‫رقم القضية ‪34165124:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34244059‬تاريخه‪1434/06/18:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي‬\n      ‫‪ -‬تعاطــي احلبــوب احملظورة‪-‬قيــادة الســيارة حتــت تأثيــر احلبــوب‬\n      ‫احملظورة‪-‬تعزيــر املدعــى عليــه بالســجن واجللــد واملنــع مــن الســفر‪-‬‬\n      ‫تــرك مجــازاة املدعــى عليــه لقــاء قيادتــه للســيارة حتــت تأثيــر احلبــوب‬\n      ‫احملظــورة للجهــة املختصة‪-‬التعزيــر بالســجن واجللــد واملنــع مــن‬\n                                           ‫الســفر ‪ -‬أســباب تخفيــف العقوبــة ‪.‬‬\n\n\n\n                                             ‫‪ -1‬اإلقرار حجة شرعية على املقر‪.‬‬\n      ‫‪ -2‬الفقــرة األولــى مــن املــادة ‪ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                             ‫العقلية‪.‬‬\n                   ‫‪ -3‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة حبــة إال ربــع مــن حبــوب‬\n      ‫اإلمفيتامــن احملظــورة بقصــد االســتعمال وتعاطيــه لهــا وقيــادة‬\n      ‫الســيارة حتــت تأثيــر تعاطيهــا‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند‬\n      ‫إليــه واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر وإثبــات قيادتــه‬\n      ‫للســيارة حتــت تأثيــر املركــب املخــدر وإفهامــه بــأن عقابــه عائــد للجهــة‬\n\n‫‪103‬‬\n\f‫املختصــة‪ ،‬مت القبــض علــى املدعــى عليــه بعــد االشــتباه بــه واســتيقافه‬\n‫مــن قبــل مكافحــة املخــدرات وبتفتيشــه قــام برمــي كيــس بــه حبــة‬\n‫إال ربــع ثبــت إيجابيتهــا لإلمفيتامــن‪ ،‬إقــرار املدعــى عليــه بالدعــوى‪،‬‬\n‫إدانــة املدعــى عليــة مبــا نســب إليــه يف الدعــوى‪ ،‬تعزيــر املدعــى عليــه‬\n‫بالســجن واجللــد واملنــع مــن الســفر‪ ،‬تــرك مجازاتــه لقــاء قيادتــه للســيارة‬\n‫حتــت تأثيــر احلبــوب احملظــورة للجهــة املختصــة‪ ،‬تصديــق احلكــم مــن‬\n                                                       ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬رئيــس احملكمــة اجلزائيــة‬\n‫يف محافظــة االحســاء املكلــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم‬\n‫‪ 34165124‬وتاريــخ ‪ 1434/04/10‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 34879396‬وتاريــخ ‪ 1434/04/10‬ه ـ حضــر املدعــي العــام ‪.............‬‬\n‫وادعــى ضــد ‪ .............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ ).............‬قائــا إنــه باإلطــاع علــى محضــر القبــض املعــد مــن قبــل‬\n‫رجــال مكافحــة املخــدرات مبحافظــة بقيــق بتاريــخ ‪1434/2/11‬ه ـ‬\n‫اتضــح أنــه أثنــاء مراقبتهــم إلحــدى محطــات الوقــود التــي يتــردد عليهــا‬\n‫أشــخاص مشــبوهون مت االشــتباه يف صاحــب ســيارة مــن نــوع (‪)......‬‬\n‫حتمــل اللوحــة رقــم (‪ ).............‬وبانتقالهــم إليــه للتأكــد منــه تبــن لهــم‬\n‫أنــه املدعــى عليــه وكان بيــده كيــس نايلــون يحــاول إخفائــه ثــم قــام‬\n‫برميــه علــى األرض بالقــرب مــن قدميــه وبتفتيــش مــا قــام برميــه ضبطــت‬\n‫حبــة إال ربــع بيضــاء اللــون يشــتبه أن تكــون مــن احلبــوب احملظــورة فتــم‬\n‫اصطحابــه ومــا ضبــط بحيازتــه وتســليمه لضابــط اخلفــر وبتحريــز‬\n\n                                                                                       ‫‪104‬‬\n\f      ‫املضبــوط بتاريــخ ‪1434/2/12‬ه ـ اتضــح أنهــا عبــارة عــن حبــة إال ربــع‬\n      ‫أعطيــت الرقــم الســري (‪ )............/ ............‬ومت إرســالها للمركــز‬\n      ‫اإلقليمــي لتحليلهــا فأثبــت التقريــر الكيماوي الشــرعي رقــم (‪).............‬‬\n      ‫بتاريخ‪1434/2/30‬ه ـ املتضمــن ثبــوت إيجابيتهــا ملركــب االمفيتامــن‬\n      ‫احملظــور وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه‬\n      ‫وأقــر بحيــازة حبــة إال ربــع مــن حبــوب االمفيتامــن احملظــورة وأقــر‬\n      ‫بتعاطيــه احلبــوب منــذ شــهر وأضــاف بأنــه قــام بشــراء حبــة مــن احلبــوب‬\n      ‫احملظــورة مــن شــخص باكســتاني اجلنســية ال يعرفــه مببلــغ (‪)100‬ريــال‬\n      ‫بقصــد االســتعمال كمــا أقــر أنــه عنــد رؤيتــه لرجــال املكافحــة يف‬\n      ‫إحــدى احملطــات قــام برميهــا بقصــد إخفائهــا عــن أعينهــم وذكــر بــأن‬\n      ‫آخــر مــرة قــام فيهــا بتعاطــي احلبــوب احملظــورة يف اليــوم الــذي قبــض‬\n      ‫عليــه فيــه وقــاد الســيارة حتــت تأثيرهــا وقــد أســفر التحقيــق عــن توجيــه‬\n      ‫االتهــام لــه بحيــازة حبــة إال ربــع مــن حبــوب اإلمفيتامــن احملظــورة بقصد‬\n      ‫االســتعمال وتعاطيــه لنوعهــا وقيــادة الســيارة حتــت تأثيرهــا وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة ‪ -1:‬إقــراره املنــوه عنــه واملــدون علــى الصفحــة‬\n      ‫رقــم(‪ )1‬مــن دفتــر التحقيــق املرفــق لفــة رقــم(‪ )12‬واملــدون علــى الصفحــة‬\n      ‫رقم(‪)3‬مــن ملــف ضبــط إجــراءات قضيــة املخــدرات املرفــق لفــة رقــم(‪)2‬‬\n      ‫‪ -2‬محضــر القبــض املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن ملــف‬\n      ‫ضبــط إجــراءات قضيــة املخــدرات املرفــق لفــة رقــم (‪ -3)1‬التقريــر‬\n      ‫الكيمــاوي الشــرعي املرفــق علــى اللفــة رقــم (‪ )19‬وبالبحــث عمــا إذا‬\n      ‫كان لديــه ســوابق اتضــح عــدم وجــود ســوابق مســجلة ضــده وحيــث إن‬\n      ‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه بحيازتــه‬\n\n\n‫‪105‬‬\n\f‫حلبــة إال ربــع مــن احلبــوب احملتويــة ملركــب االمفيتامــن احملظــور‬\n‫وتعاطيــه لنوعــه وفق ـ ًا للفقــرة رقــم (‪)2‬مــن املــادة رقــم (‪)3‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريخ‪1426/7/8‬ه ـ وقيادتــه الســيارة حتــت تأثيــره واحلكــم‬\n‫عليــه باآلتــي ‪ -1:‬عقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم (‪ )41‬مــن النظــام املشــار إليــه لقــاء حيــازة حبــة إال ربــع مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد االســتعمال وتعاطيــه لنوعهــا‪ -2‬منعــه‬\n‫مــن الســفر وفــق الفقــرة رقم(‪)1‬مــن املــادة رقم(‪)56‬مــن ذات النظــام‪-3 .‬‬\n‫إثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر مركــب االمفيتامــن املخــدر‬\n‫وفقـ ًا للفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬هـ ـ وإفهامــه بــأن‬\n‫عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬و املــادة رقــم‬\n‫(‪ )76‬مــن النظــام املشــار إليــه آنفـ ًا تقررهــا اجلهــة املختصــة وفقـ ًا للفقــرة‬\n‫رقــم (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف ‪1428/10/24‬ه ـ‬\n‫ا أصــادق علــى مــا‬ ‫وبعــرض تلــك الدعــوى علــى املدعــى عليــه أجــاب قائـ ً‬\n‫ذكــره املدعــي العــام مــن حيازتــي حبــه إال ربــع مــن حبــوب اإلمفيتامــن‬\n‫املنبــه احملظــور وقصــدي مــن حيازتهــا االســتعمال كمــا أصــادق علــى‬\n‫اســتعمالي واحلبــوب احملظــورة وقيادتــي للســيارة وأنــا حتــت تأثير احلبوب‬\n‫احملظــورة وأنــا نــادم علــى ذلــك لــذا وبعــد ســماع الدعــوى واإلجابــة‬\n‫وتصفــح أوراق املعاملــة وحيــث طلــب املدعــي العــام إثبــات إدانــة املدعــى‬\n‫عليــه حليازتــه احلبــوب احملظــورة بقصــد االســتعمال ومجازاتــه لقــاء ذلــك‬\n‫والســتعماله لهــا وإن املدعــى عليــه قــد أقــر بذلــك وإن اإلقــرار حجــة‬\n‫شــرعية علــى املقــر وإن مــا أقــدم عليــه املدعــى عليــه حــرام وإجــرام وان‬\n\n\n                                                                                         ‫‪106‬‬\n\f      ‫املدعــي العــام قــد طلــب تطبيــق العقوبــة الــواردة يف الفقــرة األولــى مــن‬\n      ‫املــادة (‪ )41‬مــن نظــام املخــدرات علــى املدعــى عليــه وإن الكميــة التــي‬\n      ‫مت ضبطهــا مــع املدعــى عليــه قليلــه و إنهــا لالســتعمال الشــخصي وملــا‬\n      ‫ظهــر لنــا مــن ندمــه وأنــه ال ســوابق عليــه وهــذه أســبابا مخففــة للعقوبــة‬\n      ‫وان املــادة (‪ )60‬مــن نظــام املخــدرات جتيــز للقاضــي النــزول عــن احلــد‬\n      ‫األدنــى مــن العقوبــة الــواردة يف بعــض مــواد ذلــك النظــام ومنهــا املــادة‬\n      ‫(‪ )41‬إذا وجــد أســباب معتبــره كمــا هــو احلــال هنــا لــذا فقــد تقــرر‬\n      ‫مــا يلــي أوال ثبــوت إدانــة املدعــى عليــه ‪ .............‬حليازتــه حبــه االربــع‬\n      ‫مــن احلبــوب احملظــورة واحملتويــة علــى مركــب اإلمفيتامــن وذلــك‬\n      ‫حســبما أوضحــه التقريــر الكيمــاوي الشــرعي رقــم (‪ ).............‬بقصــد‬\n      ‫االســتعمال ومجازاتــه لقــاء ذلــك بســجنه شــهرين تبــدأ مــن تاريــخ إيقافــه‬\n      ‫بســبب هــذه القضيــة ثاني ـ ًا تعزيــره الســتعماله احلبــوب احملظــورة وذلــك‬\n      ‫بجلــده ســبعني جلــده مفرقــه علــى فترتــن متســاويتني بينهمــا اســبوعا‬\n      ‫ثالثـ ًا منعــه مــن الســفر ملــدة ســنتني تبــدأ بعــد انتهــاء محكوميتــه رابعــا‬\n      ‫ثبــوت إدانتــه بقيــادة الســيارة حتــت تأثيــر احلبــوب احملظــورة وتركــت‬\n      ‫مجازاتــه يف ذلــك للجهــة املختصــة وبذلــك كلــه حكمــت وبعرضــه‬\n      ‫قــرر املدعــي العــام عــدم قناعتــه بــه وطلــب رفعــه حملكمــة االســتئناف‬\n      ‫مكتفيــا مبــا جــاء يف دعــواه عــن تقــدمي الئحــة اعتراضيــه أمــا املدعــى‬\n      ‫عليــه فقــرر قناعتــه بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/1442511‬ج‪ 2‬وتاريــخ ‪1434/6/14‬ه ـ‬\n\n\n‫‪107‬‬\n\f‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف الشــيخ ‪ .............‬برقــم ‪ 341174032‬وتاريــخ ‪1434/6/7‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلتــه املســجل برقــم ‪34223765‬‬\n‫وتاريــخ ‪1434/5/27‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ .............‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                  ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/6/18‬هــ‪.‬‬\n\n\n\n\n                                                                                   ‫‪108‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":103,"source_page_end":108,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b86bcc7610d4b60a163916e63e37731fa9c2fba6304e550a7bff98c9764c6f2b","normalized_text_hash":"927f03159b0251b3cb963a33971ce5f4b2c618ec8231bb9951f951c27f6fb32f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p103-3423765"},{"id":"13681a77-e578-59ac-a50c-2c557840edb9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إدانة باحليازة املجردة عن القصد -نزول عن احلد األدنى للعقوبة- تعزير بالسجن واجللد واملنع من السفر.","document_number":"3417638","case_number":"3426830","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/17","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إدانة باحليازة املجردة عن القصد -نزول عن احلد األدنى للعقوبة- تعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3417638:‬تاريخه ‪1434/01/17 :‬هـ‬\n                          ‫رقم الدعوى ‪3426830:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 3464692‬تاريخه ‪1434/3/17 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا ‪ -‬إدانــة‬\n      ‫باحليــازة املجــردة عــن القصــد ‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‪-‬‬\n                                  ‫تعزيــر بالســجن واجللــد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قول اهلل تعالى‪(( :‬من وجد يف رحله فهو جزاؤه))‪.‬‬\n      ‫‪ -2‬املــواد (‪ )39‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                  ‫العقليــة‪.‬‬\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة حبــوب اإلمفيتامــن احملظــورة بقصــد االســتعمال واســتعماله‬\n      ‫لهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت تفتيــش الســيارة التــي‬\n      ‫يقودهــا فعثــر فيهــا علــى نصــف حبــة مــن احلبــوب احملظــورة كانــت‬\n      ‫موضوعــة يف درج الســيارة‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة املرســلة لإلمفيتامــن‪ ،‬أقــر أمــام جهــة التحقيــق بحيازتــه‬\n      ‫للحبــوب احملظــورة بقصــد التعاطــي‪ ،‬أنكــر أمــام احملكمــة مــا أســنده‬\n      ‫إليــه املدعــي العــام مــن حيازتهــا بقصــد التعاطــي وأقــر بحيازتــه لهــا‬\n\n‫‪109‬‬\n\f‫لغيــر قصــد االســتعمال والبيــع‪ ،‬قضــت احملكمــة بإدانتــه بحيــازة‬\n‫احلبــوب احملظــورة حيــازة مجــردة وتعاطيــه لهــا يف الســابق وصرفــت‬\n‫النظــر عــن إدانتــه بحيازتهــا لقصــد االســتعمال وقــررت ســجنه ملــدة‬\n‫شــهرين ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني وجلــده ســبعني‬\n‫جلــدة دفعــة واحــدة علنــا الســتعماله احلبــوب احملظــورة يف الســابق‪ ،‬قنــع‬\n‫املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة‬\n                                     ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 3426830‬وتاريــخ ‪1434/01/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34130442‬وتاريــخ ‪1434/01/17‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافق‪1434/01/20‬ه ـ افتتحــت اجللســة الســاعة ‪09 :00‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .......‬وادعــى علــى احلاضــر معــه ‪.......‬ســعودي‬\n‫اجلنســية مبوجــب بالســجل املدنــي رقــم (‪ ).......‬بصفتــي مدعي ـ ًا عام ـ ًا‬\n‫بدائــرة االدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود الشــمالية أدعــي‬\n‫علــى املذكــور أعــاه فإنــه بتاريــخ ‪1433/11/28‬ه ـ أثنــاء قيــام فرقــة‬\n‫املخــدرات بعملهــا املعتــاد بحــي (‪ ).....‬مت االشــتباه بســيارة مــن نــوع (‪).....‬‬\n‫حتمــل اللوحــة رقــم (‪ )....‬كانــت تتجــول يف احلــي فيهــا شــخص واحــد‬\n‫وباســتيقافه اتضــح أنــه يدعــى‪ .......‬وبتفتيشــه شــخصي ًا لــم يعثــر علــى‬\n‫شــيء وبتفتيــش ســيارته عثــر علــى نصــف حبــة مــن احلبــوب احملظــورة‬\n‫كانــت موضوعــه يف درج الســيارة ‪ ،‬فتــم القبــض عليــه وبســماع أقوالــه‬\n\n                                                                                        ‫‪110‬‬\n\f      ‫واســتجوابه أقــر بحيــازة نصــف حبــة مــن احلبــوب احملظــورة بقصــد‬\n      ‫االســتعمال ‪ ،‬واســتعماله لهــا وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫الصادر من مركز السموم بتبوك رقم (‪3221‬م‪/‬م س ت) لعام ‪1433‬هـ‬\n      ‫إيجابيــة العينــة املرســلة ملــادة اإلمفيتامــن املنبه للجهــاز العصبي وهو من‬\n      ‫املؤثــرات العقليــة اخلاضعــة للرقابــة واملنــوه عنــه باجلــدول الثانــي فئــة (ب)‬\n      ‫يف تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪)89400/19‬‬\n      ‫وتاريــخ ‪1426/10/25‬ه ـ وقــد انتهــى التحقيــق إلــى اتهــام‪ .......‬بحيــازة‬\n      ‫نصــف حبــة مــن احلبــوب احملتويــة علــى مــادة اإلمفيتامــن احملظــورة‬\n      ‫بقصــد االســتعمال واســتعماله لهــا وبالبحــث عــن ســوابقه تبــن وجــود‬\n      ‫ســابقة حيــازة و اســتعمال مخــدرات وحيــث أن مــا أقــدم عليــه املتهــم‬\n      ‫املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب‬\n      ‫عليــه شــرعا ومجــرم نظامــا بنــص املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n      ‫وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n      ‫عليــه مبــا يلي‪-1-:‬عقوبــة الســجن وفقــا للفقــرة األولــى مــن املــادة (‪)41‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وإعمــال الفقــرة‬\n      ‫األولــى مــن املــادة (‪ )62‬مــن نفــس النظــام ‪-2‬عقوبــة املنــع مــن الســفر‬\n      ‫خــارج اململكــة وفقــا للفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام نفســه‬\n      ‫ا ال صحــة‬   ‫هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n      ‫ملــا ذكــره املدعــي العــام يف دعــواه ضــدي ونســبه إلــي من أتهامــي بحيازة‬\n      ‫نصــف حبــة مــن احلبــوب احملتويــة علــى اإلمفيتامــن احملظــورة بقصــد‬\n      ‫االســتعمال واســتعماله لهــا مــن الســابق وأمــا إقــراري لــدى مكافحــة‬\n      ‫املخــدرات وعنــد التحقيــق واالدعــاء العــام صحيــح لكــن يف الواقــع أن‬\n\n\n‫‪111‬‬\n\f‫نصــف احلبــة ليــس لــي عالقــة بهــا ووجــدت يف ســيارتي وأنــا املســتخدم‬\n‫الفعلــي لهــا وبعــض املــرات يســتخدمها أشــقائي وال علم لــي بهذه النصف‬\n‫مــن احلبــة لكنــي أقريــت بذلــك بطوعــي واختيــاري وليــس مــن إكــراه‬\n‫أو إجبــار مــن أحــد بــل ملــا شــاهدت أعضــاء الفرقــة شــهدوا علــي بذلــك‬\n‫وشــهادة اثنــن يكتفــي فيهــا قطــع الرقــاب فأقريــت بذلــك كمــا أننــي‬\n‫أصــادق علــى الســابقة املســجلة ضــدي وهــي حيــازة واســتعمال مخــدرات‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح هــو مــا‬\n‫ذكرتــه يف دعــواي وليــس لــدي بينــة علــى ذلــك ســوى مــا ورد يف أوراق‬\n‫املعاملــة هكــذا قــال ثــم جــرى منــي االطــاع علــى التقريــر الكيميائــي‬\n‫واملــدون علــى اللفــة رقــم ‪ 24‬كمــا مت االطــاع علــى أقــوال املدعــى عليــه‬\n‫لــدى مكافحــة املخــدرات واملدونــة علــى اللفــة رقــم ‪ 1‬ص‪ 18‬واملتضمــن‬\n‫فيهمــا وفــق مــا ذكــره املدعــي العــام يف دعــواه وكذلــك أقوالــه لــدى‬\n‫هيئــة التحقيــق ص ‪ 10‬و ‪ 11‬واملتضمــن فيهمــا إقــرار املدعــى عليــه (‪).....‬‬\n‫بحيــازة نصــف حبــة محظــورة بقصــد االســتعمال واســتعماله لهــا مــن‬\n‫الســابق كمــا جــرى االطــاع علــى محضــر القبــض واملــدون علــى اللفــة‬\n‫رقــم ‪ 1‬ص ‪ 11‬واملتضمــن فيــه وفــق مــا ذكــره املدعــي العــام يف دعــواه‬\n‫وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــر فيهــا كلــه صحيــح‬\n‫ا‬\n‫ثــم ذكــر جوابــه الســابق ثــم ســألته قصــده مــن احليــازة فأجــاب قائ ـ ً‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬ ‫ليــس لالســتعمال وال للبيــع فبنـ ً‬\n‫ونظــر ًا ملصادقــة املدعــى عليــه علــى إقــراره حتقيقـ ًا مــن حيازتــه لنصــف‬\n‫حبــه مــن احلبــوب احملتويــة علــى مــادة اإلمفيتامــن احملظــورة لغيــر قصــد‬\n‫حيــازة مجــرة واســتعماله لهــا مــن الســابق ونظــر ًا إلقــراره بأنــه أقــر بذلــك‬\n‫بطوعــه واختيــاره ومبــا أنــه ال عــذر ملــن أقــر وبعــد االطــاع علــى أقــوال‬\n\n\n                                                                                         ‫‪112‬‬\n\f      ‫املدعــى عليــه لــدى التحقيــق ونظــر ًا ملــا جــاء يف محضــر القبــض ونظــر ًا‬\n      ‫إليجابيــة التقريــر الكيميائــي الشــرعي املذكــورة جميعـ ًا بعاليــه وممــا‬\n      ‫يقــوي التهمــة أيضـ ًا وجــود ســابقة مســجلة ضــدي وهــي حيازة واســتعمال‬\n      ‫مخــدرات لقولــه تعالــى [ مــن وجــد يف رحلــه فهــو جــزاؤه ] لــذا وجلميــع‬\n      ‫مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة نصــف حبــة مــن‬\n      ‫احلبــوب احملتويــة علــى مــادة اإلمفيتامــن حيــازة مجــردة لغيــر قصــد‬\n      ‫واســتعماله للحبــوب مــن الســابق وصرفــت النظــر عــن طلــب املدعــي‬\n      ‫العــام بخصــوص مطالبتــه بتطبيــق املــادة ‪ 41‬مــن نظــام مكافحــة‬\n      ‫املخــدرات لثبــوت إدانــة املدعــى عليــه بحيــازة نصــف حبــة لغيــر قصــد‬\n      ‫ونظــر ًا لقلــة الكميــة وهــي نصــف حبــة فقــد أعملــت املادتــن ‪ 39‬و ‪60‬‬\n      ‫مــن نظــام مكافحــة املخــدرات وحكمــت عليــه تعزيــر ًا وذلــك بســجنه‬\n      ‫ملــدة شــهرين اعتبــار ًا مــن تاريــخ إيقافــه يف ‪1433/11/28‬ه ـ ومنعــه مــن‬\n      ‫الســفر خــارج اململكــة ملــدة ســنتني بعــد انتهــاء محكوميــة الســجن‬\n      ‫ـاء علــى املــادة ‪ 56‬مــن النظــام نفســه وجلــده ســبعني‬\n                                                               ‫املذكــورة أعــاه بنـ ً‬\n      ‫جلــدة دفعــة واحــدة علنـ ًا لقــاء اســتعماله للحبــوب احملظــورة مــن الســابق‬\n      ‫بهــذا حكمــت وبعرضــه علــى املدعــى عليــه قــرر القناعــة باحلكــم أمــا‬\n      ‫املدعــي العــام فقــرر املعارضــة علــى احلكــم بــدون الئحــة واالكتفــاء‬\n      ‫مبــا ورد يف أوراق املعاملــة وقــررت بعــث كامــل املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/01/20‬ه ـ احلمــد هلل‬\n      ‫وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/04/02‬هـ افتتحت اجللســة‬\n      ‫الســاعة ‪09.30‬وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف باجلــوف‬\n      ‫برقــم ‪ 34409371‬يف ‪1434/03/24‬ه ـ املرفــق بهــا قــرار الدائــرة الثانيــة‬\n\n\n‫‪113‬‬\n\f‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف ذي‬\n‫الرقــم ‪ 3464692‬يف ‪1434/03/17‬ه ـ واملتضمــن علــى املصادقــة علــى‬\n‫احلكــم ضــد املدعــى عليــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/04/02‬ه ـ‬\n\n\n\n\n                                                                              ‫‪114‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":109,"source_page_end":114,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2d1778c76dc590263e25c703e0221dfe254e633da73da50c44a83237dab54ff4","normalized_text_hash":"9c1ac9b7d8c23ef170f3535c528ba6056dade17e4796dfe4b64ff877f1b0f3e4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p109-3417638"},{"id":"e3ef3584-2678-54b8-809a-da5ef6bc2ddd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة -تعاطي احلبوب احملظورة- إقرار حتقيق ا -تعزير بالسجن واجللد -تخفيف عقوبة.","document_number":"3430122","case_number":"33466373","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة ......وعليه أجيب أصحاب الفضيلة وفقهم اهلل بأنه مت اتخاذ","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/14","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة -تعاطي احلبوب احملظورة- إقرار حتقيق ا -تعزير بالسجن واجللد -تخفيف عقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3430122 :‬تاريخه‪1433/07/14 :‬هـ‬\n                         ‫رقم الدعوى‪33466373:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34218906‬تاريخه‪1434/5/21:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة‪ -‬تعاطــي احلبــوب احملظــورة‪-‬‬\n              ‫إقــرار حتقيق ـ ًا‪ -‬تعزيــر بالســجن واجللــد‪ -‬تخفيــف عقوبــة‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قول اهلل تعالى ( وال تلقوا بأيديكم إلى التهلكة )‪.‬‬\n             ‫‪ -2‬قوله تعالى ( ويحل لهم الطيبات ويحرم عليهم اخلبائث )‪.‬‬\n               ‫‪ -3‬مشروعية التعزير يف كل معصية ال حد فيها وال كفارة‪.‬‬\n                   ‫‪ -4‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n      ‫‪ -5‬الفقــرة ‪ 1‬مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                      ‫العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بتوجيــه االتهــام إليــه بحيــازة‬\n      ‫احلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه الســابق لهــا‪ ،‬وطلــب‬\n      ‫املدعــي العــام إثبــات مــا اســند إليــه واحلكــم بعقوبــة الســجن واملنــع‬\n      ‫مــن الســفر‪،‬مت القبــض علــى املدعــى عليــه بعــد أن عثــر يف ثوبــه باجليــب‬\n      ‫العلــوي علــى خمــس حبــات يشــتبه أنهــا مؤثــرة عقليـ ًا وذلــك يف ســكنه‬\n      ‫كمــا عثــر حتــت ســريره علــى حبــة واحــدة يشــتبه أن تكــون مؤثــرة‬\n      ‫عقلي ـ ًا وصــدر التقريــر الكيميائــي بإيجابيــة العينــة املرســلة‪ ،‬إقــرار‬\n\n‫‪115‬‬\n\f‫املدعــى عليــه‪ ،‬ثبــوت إدانــة املدعــى عليــه‪ ،‬تعزيــر املدعــى عليــه بالســجن‬\n‫واجللــد واملنــع مــن الســفر‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي باحملكمــة اجلزئيــة‬\n‫مبحافظــة جــدة القائــم بعمــل فضيلــة الشــيخ ‪ .....‬مبوجــب خطــاب‬\n‫التكليــف رقــم ‪ .....‬يف ‪ .......‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة يف محافظــة جــدة املســاعد برقــم ‪ ......‬وتاريــخ‬\n‫‪ ........‬املقيــدة باحملكمــة برقــم ‪ .......‬وتاريــخ ‪ .......‬ففــي يــوم اإلثنــن‬\n‫املوافق‪ ..........‬افتتحت اجللسة الساعة ‪ 10 : 00‬وفيها قدم املدعي العام‬\n‫‪ .......‬دعــواه ضــد ‪ )38( ، ........... /‬عامـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب‬\n‫الهويــة الوطنيــة رقــم (‪ ،).........‬املهنــة عســكري ‪ ،‬متعلــم ‪ ،‬محصــن ‪،‬‬\n‫يقيــم مبحافظــة جــدة حــي ‪ ،.......‬أفــرج عنــه بالكفالــة احلضوريــة بتاريــخ‬\n‫‪ ........‬مبوجــب أمــر اإلفــراج رقــم (‪ )...........‬وتاريــخ ‪..........‬اســتناد ًا للمادة‬\n‫(‪ )120‬مــن نظــام اإلجــراءات اجلزئيــة املقبــوض عليــه بتاريــخ ‪ ......‬مــن‬\n‫قبــل شــعبة مكافحــة املخــدرات بالقطــاع الغربــي باحلــرس الوطنــي إثــر‬\n‫ضبــط (‪ )5‬خمــس حبــات يشــتبه أنهــا مؤثــرة عقليـ ًا باجليــب العلــوي للثوب‬\n‫العائــد لــه والــذي عثــر عليــه بــدوالب املالبــس اخلــاص بــه بالغرفــة التــي‬\n‫كان نائمـ ًا بداخلهــا كمــا عثــر حتــت مرتبــة ســريرة علــى حبــة واحــدة‬\n‫يشــتبه أنهــا مؤثــرة عقلي ـ ًا ‪ ،‬وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم (‪ ).......‬لعــام ‪1433‬ه ـ احتــواء اخلمــس حبــات املضبوطــة واملرســلة‬\n‫للتحليــل علــى مــادة اإلمفيتامــن املؤثــرة عقليـ ًا املــدرج بجــدول املخــدرات‬\n‫رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n\n                                                                                             ‫‪116‬‬\n\f      ‫وخلــو احلبــة املضبوطــة حتــت املرتبــة مــن املــواد املخــدرة وبســماع أقوالــه‬\n        ‫أقــر بحيــازة ملــا مت ضبطــه بقصــد التعاطــي وبتعاطيــه الســابق لنوعهــا ‪.‬‬\n      ‫وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام إليــه بحيــازة (‪ )5‬خمــس‬\n      ‫حبــات حتتــوي علــى مــادة األمفيتامــن املؤثــرة عقلي ـ ًا بقصــد التعاطــي‬\n      ‫وبتعاطيــه الســابق لنوعهــا ‪ ،‬املجــرم اســتناد ًا للفقــرة (‪ )2‬مــن املــادة‬\n      ‫(الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وذلــك‬\n                                                                    ‫لألدلــة والقرائــن التاليــة‪:‬‬\n                                         ‫‪ .1‬ما ورد يف إقراره املنوه عنه املرفق لفة (‪.)5‬‬\n         ‫‪ .2‬ما ورد بشهادة الشهود مبحضر الضبط املنوه عنه املرفق لفـة (‪. )1‬‬\n      ‫‪ .3‬مــا ورد يف التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة (‪)25‬‬\n      ‫وباالطــاع علــى ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة عليــه وحيــث‬\n      ‫إن مــا أقــدم عليــه املدعــى عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬لــذا أطلــب إثبــات مــا أســند إليــه‬\n                      ‫واحلكــم عليــه بالعقوبتــن األصليــة والتكميليــة التاليتــن ‪:‬‬\n      ‫‪ .1‬بالســجن لقــاء مــا أســند إليــه اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن‬\n                                                 ‫نظــام مكافحــة املخــدرات املشــار إليــه‪.‬‬\n      ‫‪ .2‬منعــه مــن الســفر خلــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه‪.‬‬\n      ‫وبعــرض مــا ورد بدعــوى املدعــي العــام علــى املدعــى عليــه احلاضــر يف‬\n      ‫ا مــا ورد يف دعــوى املدعــي العــام مــن‬              ‫املجلــس الشــرعي قــرر قائ ـ ً‬\n      ‫توجيــه االتهــام لــي بحيــازة خمــس حبــات حتتــوي علــى مــادة اإلمفيتامني‬\n\n\n‫‪117‬‬\n\f‫املؤثــرة عقلي ـ ًا بقصــد التعاطــي وتعاطيــه لنوعهــا مــن الســابق فصحيــح‬\n‫ا هــذا وحيــث جــرى االطــاع علــى أوراق املعاملة فوجدت‬           ‫جملــه وتفصيـ ً‬\n‫األدلــة والقرائــن التالية‪.1‬مــا ورد يف إقــراره املنــوه عنــه املرفــق لفــة (‪)5‬‬\n‫‪.2‬مــا ورد بشــهادة الشــهود مبحضــر الضبــط املنــوه عنــه املرفــق لف ــة (‪. )1‬‬\n‫‪ .3‬مــا ورد يف التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n‫(‪ )25‬فوجــدت جميــع مــا تقــدم طبق ـ ًا ملــا ذكــر املدعــي العــام فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه مبــا ورد‬\n‫ا وحيــث أن الشــريعة‬        ‫يف دعــوى املدعــي العــام ضــده جملــه وتفصي ـ ً‬\n‫اإلســامية جــاءت بحفــظ الضروريــات اخلمــس الديــن والنفــس والعقــل‬\n‫واملــال والعــرض وهــذه اآلفــة مذهبــه للديــن ومهلكــه للنفــس ومفســده‬\n‫للعقــل مضيعــة للمــال والعــرض ولقولــه تعالــى { وال تلقــوا بأيديكــم إلــى‬\n‫التهلكــة} وقولــه تعالــى {ويحــل لهــم الطيبــات ويحــرم عليهــم اخلبائــث}‬\n‫ولنهيــه صلــى اهلل عليــه وســلم عــن كل مســكر ومفتــر وملــا يف ذلــك‬\n‫الضــرر علــى املدعــى عليــة وعلــى املجتمــع بأســره ومــا تســببه مــن انحالل‬\n‫وتدميــر وانتشــار للفســاد والرذيلــة وملــا يف فعــل املدعــى عليه من عصيان‬\n‫هلل ولرســوله ولولــي األمــر وحيــث إن التعزيــر مشــروع يف كل معصيــة‬\n‫ال حــد فيهــا وال كفــاره فبنــاء علــى جميــع مــا ســبق فقــد ثبــت لــدي‬\n‫إدانــة املدعــى عليــه بحيــازة خمــس حبــات حتتــوي علــى مــادة اإلمفيتامــن‬\n‫املؤثــرة عقليـ ًا بقصــد التعاطــي وتعاطيــه لنوعــه مــن الســابق ونظــر ًا لعــدم‬\n‫وجــود ســوابق للمدعــى عليــه وإظهــاره للتوبــة والنــدم وعــدم العــودة لفعلــه‬\n‫فقــد حكمــت عليــه لقــاء ذلــك مبــا يلــي أو ًال ســجنه ملــدة شــهرين حتســب‬\n‫منهــا مــده إيقافــه علــى ذمــة هــذه القضيــة وفقـ ًا للمــادة ( ‪ ) 60‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ثانيـاً‪ /‬منعــه مــن الســفر خلــارج‬\n\n\n                                                                                       ‫‪118‬‬\n\f      ‫اململكــة بعــد انتهــاء تنفيــذ محكوميتــه ملــدة ســنتني وفق ـ ًا للفق ـ ـ ــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه وبعرضــه علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه القناعــة وقــرر املدعــي العــام عــدم القناعــة وطلــب‬\n      ‫االســتئناف فأجبتــه لطلبــه وســيجري اتخــاذ الــازم حســب التعليمــات‬\n      ‫جــرى النطــق باحلكــم يف متــام الســاعة العاشــرة والربــع وصلــى اهلل‬\n                               ‫وســلم علــى نبينــا محمــد حــرر يف ‪1434/02/04‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪ ......‬افتتحــت اجللســة‬\n      ‫الســاعة العاشــرة وكانــت املعاملــة قــد عــادت مــن محكمــة االســتئناف‬\n      ‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم ‪ ....‬وتاريــخ‬\n      ‫‪ ........‬واملتضمــن أنــه بدراســة القــرار وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن صــورة‬\n      ‫الضبــط غيــر مختومــة بختــم احلكــم والتوقيــع عليهــا صــورة طبق األصل‬\n      ‫إلكمــال الــازم واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم قاضــي اســتئناف ‪ ......‬قاضــي اســتئناف ‪ .........‬رئيــس‬\n      ‫الدائــرة ‪ ......‬وعليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل بأنــه مت اتخــاذ‬\n      ‫الــازم حيــال املالحظــة املذكــورة وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                               ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪.......‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــا ال نبــي بعــده ‪ ،‬وبعــد ‪:‬ـ فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة بجــدة برقــم ‪ ......‬وتاريــخ ‪.......‬املرفــق بهــا‬\n      ‫القــرار الشــرعي رقــم ‪ ......‬وتاريــخ ‪......‬الصــادر مــن فضيلــة الشــيخ‪.......‬‬\n      ‫القاضــي يف احملكمــة اجلزائيــة بجــدة املتضمــن دعــوى املدعــي العــام‬\n\n\n‫‪119‬‬\n\f‫ضــد ‪ .....‬املتهــم يف مخــدرات احملكــوم فيــه مبــا دون باطنــه‪ ،‬واملالحظ‬\n‫عليــه بقــرار محكمــة االســتئناف برقــم‪ ....‬وتاريــخ‪ ......‬وبدراســة القــرار‬\n‫وصـ ـ ــورة ضبطــه تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‪،‬‬\n ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪120‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":115,"source_page_end":120,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8866f5e25e422af8339051296c8eceeb0b269b10ccfd2d79a314f80effb09d37","normalized_text_hash":"2f7e1e3a9ef72cdc8800f1cdcc84903921e061a29a3a46a1ddf682d9ff853827","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p115-3430122"},{"id":"a6e1939b-8d5a-5792-96f0-ae850bae0677","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -محاولة الهرب من رجال األمن -إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -تعزير بالسجن واجللد واملنع من السفر والغرامة.","document_number":"3452025","case_number":"3440682","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/01","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -محاولة الهرب من رجال األمن -إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -تعزير بالسجن واجللد واملنع من السفر والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3452025 :‬تاريخه‪1434/03/01 :‬هـ‬\n                           ‫رقم الدعوى‪3440682:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34258546‬تاريخه‪1434/7/3:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه وتســتر علــى‬\n      ‫مصــدره‪ -‬محاولــة الهــرب مــن رجــال األمــن‪ -‬إثبــات بالشــهادة‪ -‬إدانــة‬\n      ‫باحليــازة املجــردة عــن القصــد ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن‬\n                                                               ‫الســفر والغرامــة‪.‬‬\n\n\n\n             ‫‪ -1‬قول اهلل تعالى‪« :‬وال تقتلوا النفس التي حرم اهلل إال باحلق»‪.‬‬\n                   ‫‪ -2‬قول اهلل تعالى‪« :‬وال تفسدوا يف األرض بعد إصالحها»‪.‬‬\n      ‫‪ -3‬املــادة (‪ )39‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n                                                                  ‫واملؤثــرات العقلية‪.‬‬\n      ‫‪ -4‬قــال يف كشــاف القنــاع‪( :‬وتعديــل اخلصــم وحــده تعديــلٌ يف حــق‬\n      ‫ألن البحــث عــن عدالتــه حلــق املشــهود عليــه وقــد اعتــرف بهــا)‪.‬‬\n                                                                         ‫الشــاهد َّ‬\n\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه ومحاولــة الهــروب‬\n      ‫مــن رجــال األمــن وتســتره علــى مصدر املخــدرات ‪ ،‬واحلكم عليه بعقوبة‬\n      ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة وبعقوبــة تعزيريــة علــى باقــي التهــم‪ ،‬مت القبــض عليــه بعــد‬\n\n‫‪121‬‬\n\f‫هربــه مــن رجــال األمــن وبتفتيشــه ضبطــت يف جيــب ثوبــه األميــن قطعــة‬\n‫يشــتبه أن تكــون مــن احلشــيش‪ ،‬أثبــت التقريــر الكيمــاوي الشــرعي‬\n‫إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬أنكــر أمــام احملكمــة مــا‬\n‫أســنده إليــه املدعــي العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي‬\n‫بيناتــه وقــررت ســماع شــهادة شــهود محضــر القبــض فشــهدوا أن قطعــة‬\n‫احلشــيش املخــدر ضبطــت يف جيبــه وأنــه هــرب منهــم قبــل القبــض عليــه‪،‬‬\n‫قضــت احملكمــة بعــدم إدانــة املدعــى عليــه باســتعمال احلشــيش املخــدر‬\n‫وحيازتــه لقصــد االســتعمال وقضــت بإدانتــه بحيازتــه حيــازة مجــردة‬\n‫وبالهــروب مــن رجــال األمــن والتســتر علــى مصــدر املخــدر وقــررت‬\n‫ســجنه ملــدة ســنتني وجلــده مائتــي جلــدة مفرقــة ومنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة ســنتني وتغرميــه مبلــغ ثالثــة آالف ريــال‪ ،‬عــارض املدعــى‬\n‫عليــه واملدعــي العــام علــى احلكــم‪ ،‬قــررت محكمــة االســتئناف‬\n                              ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬\n                  ‫أنــا‪ .......‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ‪ 1141‬وتاريــخ ‪1434/01/21‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪34198840‬وتاريــخ ‪1434/01/24‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n‫الرئيــس برقم‪3440682‬وتاريــخ ‪1434/01/24‬ه ـ فتحــت اجللســة األولــى‬\n‫يــوم االثنــن ‪1434/02/11‬ه ـ الســاعة الثامنــة والنصــف وفيهــا حضــر‬\n‫املدعــي العــام امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب‬\n\n                                                                                    ‫‪122‬‬\n\f      ‫ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء ذي‬\n      ‫ا بصفتــي‬    ‫الرقــم ‪ 13415‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى‬\n      ‫‪ .......‬البالــغ مــن العمر(‪)25‬عام ـ ًا ‪.......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .......‬متســبب ‪ ،‬غيــر محصــن‪ ،‬قبــض عليــه بتاريــخ‬\n      ‫‪1433/12/1‬ه ـ وأوقــف مبوجــب أمــر اإليقــاف الصــادر مــن دائــرة‬\n      ‫التحقيــق واالدعــاء العــام مبحافظــة األحســاء برقــم (ه ـ ق‪ )2/2‬وتاريــخ‬\n      ‫‪1433/12/2‬ه ـ وفق ـ ًا لبرقيــة وزيــر الداخليــة رقــم (‪)794254/5/1‬‬\n      ‫وتاريــخ ‪1432/12/20‬ه ـ وجــرى التمديــد لــه ملــدة (‪ )25‬يومــا اعتبــار ًا‬\n      ‫مــن ‪1433/12/7‬ه ـ بأمــر التمديــد الصــادر مــن فــرع الهيئــة باملنطقــة‬\n      ‫الشــرقية برقــم (ه ـ ق‪ )75630/5/1‬يف ‪1433/12/8‬ه ـ وأحيــل إلــى‬\n      ‫شــعبة ســجن محافظــة األحســاء انــه بتاريــخ ‪1433/12/1‬ه ـ مت القبــض‬\n      ‫عليــه مــن قبــل إحــدى فــرق مكافحــة املخــدرات التابعــة حملافظــة‬\n      ‫األحســاء اثــر توفــرت معلومــات عــن وجــود مجموعــة مــن محتــازي‬\n      ‫املخــدرات علــى طريــق ‪ .....‬وبعــد االنتقــال للموقــع لوحــظ املدعــى عليــه‬\n      ‫يســير علــى قدميــه وعنــد مشــاهدته للفرقــة فــر هاربـ ًا علــى قدميــه فتــم‬\n      ‫اللحــاق بــه والقبــض عليــه وأثنــاء القبــض عليــه حــاول الهــروب مــن رجــال‬\n      ‫أألمــن ومتــت مطاردتــه والقبــض عليــه وبتفتيشــه ضبــط يف جيــب ثوبــه‬\n      ‫األميــن علــى والعــة ملصــق بهــا قطعــه ســوداء اللــون بلــغ وزنهــا (‪0،2‬جــم)‬\n      ‫اثنــان مــن العشــرة مــن اجلــرام يشــتبه أن تكــون مــن احلشــيش املخــدر‬\n      ‫أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪4481‬ك ش) لعــام ‪1433‬ه ـ‬\n      ‫إيجابيــة عينــة القطعــة املضبوطــة للحشــيش املخــدر احملظــور واملــدرج‬\n      ‫يف اجلــدول مــن ضمــن املــواد احملظــورة (‪ )1‬فئــة (أ) مــن نظــام مكافحــة‬\n\n\n‫‪123‬‬\n\f‫املخــدرات واملؤثــرات العقليــة‪ ،‬كمــا أثبــت تقرير الســموم الشــرعي رقم‬\n‫(‪ )1599‬لعــام ‪1433‬ه ـ إيجابيــة عينــة بولــه ملركــب احلشــيش املخــدر‪.‬‬\n‫وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبــض وأنكــر حيازتــه‬\n‫للقطعــة املضبوطــة أو تعاطيــه للحشــيش املخــدر‪ .‬وقــد اســفر التحقيــق‬\n‫عــن توجيــه االتهــام لــه بحيــازة قطعــة مــن احلشــيش تــزن (‪ )0،2‬اثنــن مــن‬\n‫العشــرة مــن اجلــرام بقصــد التعاطــي وتعاطيــه لنوعــه ومحاولــة الهــروب‬\n‫مــن رجــال األمــن وتســتره علــى مصــدر املخــدرات وذلــك لألدلــة والقرائن‬\n‫التالية‪ -1 - :‬ما جاء يف محضر القبض املدون على الصفحة رقم (‪)12‬‬\n‫مــن دفتــر االســتدالل لفــة رقــم (‪ -2 .)8‬مــا جــاء يف التقريــر الكيمــاوي‬\n‫للقطعــة املضبوطــة املرفــق لفــة (‪-3.)30،29‬ماجــاء يف تقريــر الســموم‬\n‫املرفــق لفــة رقــم (‪ .)21‬وبالبحــث عــن ســوابقه تبــن وجــود خمــس ســوابق‬\n‫جنائيــة األولــى اســتعمال مخــدرات والثانيــة ارتــكاب عــدة ســرقات‬\n‫وســرقة مســاكن والثالثة اســتعمال مخدرات والرابعة مخالفة تعليمات‬\n‫واخلامســة حيــازة واســتعمال مخــدرات وتوســط يف بيــع وشــراء مخــدرات‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ اطلــب‬\n                             ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪ .1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظام املشــار‬\n‫إليــه ‪ ،‬وتشــديد العقوبــة عليــه لقــاء تعــدد ســوابقه اســتناد ًا لبرقيــة نائــب‬\n                 ‫وزيــر الداخليــة رقم (‪ )93958/5/5/1‬يف ‪1429/8/23‬هـ‪.‬‬\n‫‪ .2‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام املشــار‬\n\n\n                                                                                        ‫‪124‬‬\n\f                                                                ‫إليــه مبنعــه مــن الســفر‪.‬‬\n      ‫‪ .3‬بعقوبــة تعزيريــة لقــاء محاولتــه الهــرب مــن رجــال األمــن ‪ ،‬وتســتره‬\n      ‫علــى مصــدر املخــدرات‪ .‬هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى‬\n      ‫عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه‬\n      ‫فأجــاب قائـاً‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي بحيــازة قطعــة مــن‬\n      ‫احلشــيش تــزن(‪ )0.2‬اثنــن مــن العشــرة مــن اجلــرام بقصــد التعاطــي‬\n      ‫وتعاطـ َّـي لنوعــه ومحاولــة الهــرب مــن رجــال األمــن وتســتري علــى مصــدر‬\n      ‫اخلمــر غيــر صحيــح والصحيــح أننــي كنــت راكبـ ًا مــع صاحــب ســيارة‬\n      ‫مت إيقافنــا وتفتيشــنا ولــم يتـ َّـم‬\n                                          ‫أجــرة إليصالــي إلــى ‪ .....‬حيــث عملــي و َّ‬\n      ‫العثــور علــى شــيء معــي وبعــد عشــر دقائــق تقريبـ ًا قــال لــي أحــد أفــراد‬\n      ‫إن هــذا القطعــة لــك وقــد وجدهــا يف الوالعــة وصحيــح نســبة‬      ‫املخــدرات َّ‬\n      ‫الســوابق اخلمــس لــي وقــد أخــذت محكوميتهــا هكــذا أجــاب ثــم جــرى‬\n      ‫ســؤال املدعــي العــام هــل لديــه بينــة علــى دعــواه فقــال‪ :‬نعــم أحضــرت‬\n      ‫ال مــن ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬          ‫للشــهادة ك ً‬\n      ‫رقــم‪ .......‬مــن مواليد‪1395/02/27‬ه ـ ‪.......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم‪ .......‬مــن مواليــد ‪1405/10/10‬ه ـ ويعمــان يف‬\n      ‫عمــا لديهمــا‬ ‫إدارة مكافحــة املخــدرات مبحافظــة األحســاء وبســؤالهما َّ‬\n      ‫مــن شــهادة شــهد كل واحــد منهمــا مبفــرده قائ ـاً‪ :‬أشــهد بــاهلل تعالــى‬\n      ‫مت‬\n      ‫أن املدعــى عليــه مــن أهــل الســوابق ورأينــاه يف داخــل محطــة فهــرب و َّ‬      ‫َّ‬\n      ‫مت تفتيشــه ووجدنــا معــه والعــة لونهــا زرقــاء ملصقـ ًا بهــا‬\n                                                                      ‫القبــض عليــه و َّ‬\n      ‫قطعــة صغيــرة مــن احلشــيش هكــذا شــهد كل واحــد منهمــا وبعــرض‬\n      ‫الشــاهدين وشــهادتهما علــى املدعــى عليــه قــال‪ :‬أمــا الشــاهدان فــا‬\n      ‫أقــول فيهمــا إال خيــر ًا وأمــا شــهادتهما فغيــر صحيحــة فالوالعــة كانــت‬\n\n\n‫‪125‬‬\n\f‫معــي وليســت ملــك ًا لــي وإمنــا هــي لســائق األجــرة وأخبرونــي يف املــرة‬\n‫األولــى أنهــم لــم يجــدوا معــي شــيئ ًا ثــم قالــوا إنهــم وجــدوا هــذه القطعــة‬\n‫هكــذا قــرر ثــم جــرى ســؤال املدعــي العــام هــل لديــه زيــادة بينــة فقــال‬\n‫نعــم وهــي موجــودة يف أوراق املعاملــة وأطلــب الرجــوع إليهــا هكــذا‬\n‫أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا‪ :‬التقريــر‬\n‫الكيمــاوي الشــرعي الصــادر مــن قســم الكيميــاء الشــرعية باملركــز‬\n‫اإلقليمــي ملراقبــة الســموم التابــع للمديريــة العامــة للشــؤون الصحيــة‬\n‫باملنطقــة الشــرقية برقــم ( ‪ 4481‬ك ش ) لعــام ‪1433‬ه ـ املتضمن إيجابية‬\n‫عي ــنة مــا ضبــط للحشــيش املخــدر كمــا جــرى االطــاع علــى كــرت‬\n‫ســوابق املدعــى عليــه املتضمــن وجــود ســابقة خمــس ســوابق عليــه كمــا‬\n‫جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املتضمنــة أنــه أوقــف‬\n‫بتاريخ‪1433/12/01‬ه ـ فبنــاء علــى مــا ورد مــن الدعــوى واإلجابــة وبعــد‬\n‫النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وملــا ورد يف محضــر‬\n‫القبــض ومبــا أنــه أنكــر دعــوى املدعــي العــام باتهامــه بحيــازة احلشــيش‬\n‫املخــدر علــى صفــة مــا ورد يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف‬\n‫الشــريعة ملــا يف احلشــيش املخــدر مــن اخلطــر و الضــرر على البــاد والعباد‬\n‫وعلــى مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم اهلل‬\n‫إال باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا ) ممــا يســتوجب‬\n‫معاقبــة املدعــى عليــه و تعزيــزه بالعقوبــة الــواردة التاســعة والثالثــن‬\n‫وعــدم اســتحقاقه للعقوبــة الــواردة يف املــادة الواحــدة واألربعــن مــن‬\n‫نظــام مكافحــة املخــدرات كمــا يتوجــه اســتحقاقه للعقوبــة الــواردة يف‬\n‫أن‬\n ‫املــادة السادســة واخلمســن مــن النظــام ذاتــه الفقــرة األولــى منهــا ومبــا َّ‬\n‫املدعــى عليــه أنكــر اســتعمال احلشــيش املخــدر وال بينــة للمدعــي العــام‬\n\n\n                                                                                         ‫‪126‬‬\n\f      ‫علــى ذلــك ممــا يســتوجب ر َّد دعــوى املدعــي العــام بإثبــات إدانتــه بذلــك‬\n      ‫ومبــا أ َّنــه أنكــر هروبــه مــن رجــال األمــن وقامــت البينــة علــى إثبــات‬\n      ‫ذلــك ممــا يســتوجب تعزيــره لــذا كلــه وألجــل احلــق العــام حكمــت علــى‬\n      ‫ـدي إدانــة املدعــى عليه باســتعمال‬  ‫املدعــى عليــه باآلتــي‪ :‬أو ًال ‪ /‬لــم يثبــت لـ َّ‬\n      ‫ـررت ر َّد دعــوى املدعــي العــام بإثبــات إدانتــه بذلــك‬  ‫احلشــيش املخــدر وقـ ُ‬\n      ‫ـدي إدانــة املدعــى عليــه بحيــازة قطعــة مــن احلشــيش‬       ‫ثاني ـ ًا ‪ /‬لــم يثبــت لـ َّ‬\n      ‫تــزن(‪ )0.2‬اثنــن مــن العشــرة مــن اجلــرام بقصــد التعاطــي وقــررت عــدم‬\n      ‫اســتحقاقه للعقوبــة الــواردة يف املــادة الواحــدة واألربعــن مــن نظــام‬\n      ‫ـدي إدانــة املدعــى عليــه بحيــازة‬‫مكافحــة املخــدرات‪ .‬ثالث ـ ًا ‪ /‬ثبــت لـ َّ‬\n      ‫قطعــة مــن احلشــيش تــزن (‪ )0.2‬اثنــن مــن العشــرة مــن اجلــرام حيــازة‬\n      ‫مجــردة وعزرتــه لقــاء ذلــك بســجنه ملــدة عامــن مــن تاريــخ إيقافــه علــى‬\n      ‫ذمــة القضيــة وذلــك اســتناد ًا علــى املــادة التاســعة والثالثــن مــن نظــام‬\n      ‫مكافحــة املخــدرات‪ .‬رابع ـ ًا ‪ /‬وأن مينــع مــن الســفر مــدة عامــن حســب‬\n      ‫مقتضــى مــا ورد يف املــادة السادســة واخلمســن مــن النظــام نفســه على أن‬\n      ‫ـدي إدانــة‬\n              ‫يكــون املنــع ابتــداء مــن انتهــاء محكوميتــه‪ .‬خامسـ ًا ‪ /‬ثبــت لـ َّ‬\n      ‫املدعــى عليــه بالهــروب مــن رجــال األمــن والتســتر على مصــدر املخدرات‬\n      ‫وعقوبتــه يف ذلــك داخلــة يف عقوبــة احليــازة وبتــاوة احلكم على الطرفني‬\n      ‫وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم وطلــب‬\n      ‫املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة‬\n      ‫الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك حرمــة‬\n      ‫اســتعمال احلشــيش املخــدر وأثــره الســيئ علــى العقــل واملــال وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف‬\n      ‫‪1434/02/27‬هــ‪ .‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n\n\n‫‪127‬‬\n\f‫بعــده وبعــد‪ :‬ففــي يــوم األربعــاء ‪1434/05/15‬ه ـ فتحــت اجللســة الثالثــة‬\n‫الســاعة الثانيــة والنصــف وقــد عــادت املعاملــة املتعلقــة بالدعــوى العامــة‬\n‫ضــد ‪ .......‬مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب خطــاب‬\n‫فضيلــة رئيســها ذي الرقــم ‪ 34/736331‬وتاريــخ ‪1434/05/12‬ه ـ‬\n‫وبرفقهــا قــرار الدائــرة اجلزائيــة األولــى(ج‪ )1/‬رقــم ‪ 34207725‬وتاريــخ‬\n‫‪1434/05/06‬ه ـ املتضمــن مــا نصــه‪« :‬وبدراســة القــرار وصــورة ضبطــه‬\n‫إن املدعــي العــام أحضــر شــاهدين‬    ‫وأوراق املعاملــة لوحــظ مــا يلــي‪ :‬أوالً‪َّ /‬‬\n‫ولــم يتــم تزكيتهمــا حســب األصــول الشــرعية‪ .‬ثاني ـ ًا ‪ /‬أثبــت فضيلتــه‬\n‫إدانــة املدعــى عليــه بحيــازة احلشــيش حيــازة مجــردة ولــم يعمــل فضيلتــه‬\n‫املــادة‪ 39‬مــن نظــام مكافحــة املخــدرات ملالحظــة ذلــك وإكمــال الــازم‬\n‫ومــن ثــم إعــادة املعاملــة واهلل املوفــق» ا‪.‬ه ـ عليــه أجيــب مشــايخي نفعنــي‬\n‫ـأن املدعــى عليــه عـ َّـدل الشــاهدين‬  ‫اهلل بعلمهــم بالنســبة للفقــرة أوالً‪ /‬بـ َّ‬\n‫ولــم يقــدح فيهمــا وال يخفــى علــى مشــايخي أ َّنــه يف حــال زكاهمــا‬\n‫املدعــى عليــه فــا داعــي إلــى تعديلهمــا‪ .‬وأمــا بالنســبة للفقــرة ثاني ـاً‪/‬‬\n‫مت إعمــال املــادة التاســعة والثالثــن مــن نظــام مكافحــة املخــدرات‬      ‫فقــد َّ‬\n‫وحكــم علــى املدعــى عليــه بالســجن ملــدة عامــن ولعــلَّ اللبــس قــد حصل‬\n‫مت تداركــه وإكمــال الــازم‬       ‫بســبب وجــود ســقط يف التســبيب وقــد َّ‬\n‫حيالــه وإضافــة مــا ســقط أثنــاء الطباعــة وإعــادة القــرار مــرة أخــرى‬\n‫ـرت بالتهميــش‬ ‫وعليــه فلــم يظهــر لــي ســوى مــا حكمــت بــه ســابق ًا وأمـ ُ‬\n‫علــى قــرار احلكــم مبــا طــرأ عليــه ومــن ثـ ّـم إعــادة املعاملــة حملكمــة‬\n‫االســتئناف باملنطقــة الشــرقية لتدقيــق احلكــم وأقفلــت اجللســة الســاعة‬\n‫الواحــدة ظهــر ًا وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫أجمعــن ُحـ ِـر َر يف ‪1434/05/15‬ه ـ ‪.‬‬\n\n\n                                                                                         ‫‪128‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪:‬‬\n      ‫ففــي يــوم األربعــاء ‪1434/07/26‬ه ـ فتحــت اجللســة اخلامســة الســاعة‬\n      ‫العاشــرة والنصــف وفيهــا حضــر الطرفــان وقــد عــادت املعاملــة‬\n      ‫املتعلقــة بالدعــوى العامــة ضــد‪ .......‬مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم‪34/1453791‬‬\n      ‫وتاريــخ ‪1434/07/19‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة األولــى(ج‪)1/‬‬\n      ‫رقم‪34258546‬وتاريخ‪1434/07/03‬ه ـ املتضمــن مــا نصــه‪« :‬وحيــث‬\n      ‫ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع علــى ما أجــاب به فضيلة‬\n      ‫ـاء على قرارنــا‪34207725‬يف‬      ‫القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n      ‫أن مــا أجــاب بــه فضيلتــه علــى قــرار الدائــرة‬ ‫‪1434/05/06‬ه ـ لوحــظ َّ‬\n      ‫غيــر وجيــه حيــث إن املدعــى عليــه لــم يقبــل شــهادة الشــاهدين وحيــث‬\n      ‫إن احلــال مــا ذكــر فــا بـ َّـد مــن تزكيتهمــا ‪ ،‬أمــا مــا أجــاب بــه فضيلتــه‬\n      ‫علــى املالحظــة الثانيــة فلــم يعمــل فضيلتــه مقتضــى املــادة(‪ )39‬مــن‬\n      ‫نظــام املخــدرات حيــث تضمنــت عقوبــات ماليــة وجزائيــة غيــر الســجن‬\n      ‫ملالحظــة ذلــك وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق»‬\n      ‫أمــا بالنســبة للفقــرة‬\n                            ‫ا‪.‬ه ـ عليــه أجيــب مشــايخي نفعنــي اهلل بعلمهــم‪َّ :‬‬\n      ‫ـأن عدالــة الشــهود تثبــت بإحــدى طــرق‬     ‫ـص الفقهــاء بـ َّ‬‫األولــى فقــد نـ َّ‬\n      ‫ثــاث ؛ ومنهــا‪ :‬تعديــل املشــهود عليــه للشــاهد‪ ،‬وهــذا مــا حصــل يف هــذه‬\n      ‫القضيــة ‪ ،‬قــال يف كشــاف القنــاع‪( :‬وتعديــل اخلصــم وحــده تعديــلٌ يف‬\n      ‫ألن البحــث عــن عدالتــه حلــق املشــهود عليــه وقــد اعتــرف‬    ‫حــق الشــاهد َّ‬\n      ‫ـإن‬\n       ‫بهــا)‪ ،‬وقــال ســماحة الشــيخ‪ :‬محمــد بــن إبراهيــم ‪-‬رحمــه اهلل‪( :-‬فـ َّ‬\n      ‫ـرار يف احلقيقــة أن‬\n                        ‫احلــق للخصــم وال يعــدوه ‪ ،‬وهــو قــد أتــى مبــا هــو إقـ ٌ‬\n      ‫ـاهد شــهادته صحيحــة فــا يحتــاج أن يأتــي ببينــة تزكيــه‪،‬‬         ‫هــذا شـ ٌ‬\n\n‫‪129‬‬\n\f‫بــل تزكيــة اخلصــم) ‪ ،‬وأمــا بالنســبة إلعمــال املــادة(‪ )39‬مــن نظــام‬\n‫مكافحــة املخــدرات فمــا ذكــره مشــايخي فصحيــح وعليــه فقــد‬\n‫حكمــت بتعزيــر املدعــى عليــه إضافــة إلــى مــا ســبق بجلــده مائتــا جلــدة‬\n‫مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة‬\n‫وأخــرى مــدة ال تقــل عــن عشــرة أيــام وبغرامــة ماليــة قدرهــا ثالثــة آالف‬\n‫ريــال وذلــك اســتناد ًا إلــى املــادة التاســعة والثالثــن مــن نظــام مكافحــة‬\n‫املخــدرات وبعــرض احلكــم علــى الطرفــن قــررا عــدم القناعــة بــه دون‬\n‫ـرت بالتهميــش علــى قــرار احلكــم مبــا طــرأ عليــه‬   ‫الئحــة اعتراضيــة وأمـ ُ‬\n‫ومــن ثـ ّـم إعــادة املعاملــة حملكمــة االســتئناف باملنطقــة الشــرقية لتدقيــق‬\n‫احلكــم وأقفلــت اجللســة الســاعة احلاديــة عشــر وصلــى اهلل وســلم علــى‬\n ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ُحـ ِـر َر يف‪1434/07/26‬ه ـ ‪.‬‬\n‫احلمــد اهلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة االحســاء املكلف برقم‬\n‫‪ 341453791‬وتاريــخ ‪1434/08/03‬ه ـ املقيــد لــدى احملكمــة برقــم‬\n‫‪ 1927984/34‬وتاريــخ ‪1434/08/09‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ .....‬املســجل برقــم ‪3452025‬‬\n‫وتاريــخ ‪1434/03/01‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪....../‬‬\n‫يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلــة القاضــي‬\n‫وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪ 34258546‬يف‬\n‫‪1434/07/03‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1434/08/17‬ه ـ ‪.‬‬\n\n\n                                                                                     ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":121,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c2d7eec7300c4727d23d45b42efdf54e2794e684c04aaf3cab2a0ad603903c80","normalized_text_hash":"d2a559aa1c12c1d00ee3368d4dbb290393259bb3333c55010bce1bc0dc765f51","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p121-3452025"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

